    "project/contracts/core/storages/ExternalTransferStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Status of an external transfer
/// @dev Tracks the lifecycle of external transfers to trusted targets (other Symmio diamonds or external contracts).
///      PENDING = initiated but not yet completed/canceled by provider
///      COMPLETED = provider accepted and deposited on target
///      CANCELED = user canceled
enum VirtualExternalTransferStatus {
	PENDING,
	COMPLETED,
	CANCELED
}

/// @notice Transfer request moving funds to a trusted target via a virtual provider
/// @dev Enables fund movement to any whitelisted target -- another Symmio diamond (e.g., perps and options)
///      or any trusted external contract. Uses virtual providers as intermediaries who credit the receiver
///      on the target. The provider must accept the transfer, or user can cancel.
struct VirtualExternalTransferRequest {
	uint256 id;
	address sender; // user in source contract
	address receiver; // recipient in target contract
	address source;
	address target;
	uint256 amount;
	uint256 timestamp;
	address provider; // virtual provider who handles the transfer
	VirtualExternalTransferStatus status;
}

/// @title ExternalTransferStorage
/// @notice Fund transfers to trusted external targets
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library ExternalTransferStorage {
	bytes32 internal constant EXTERNAL_TRANSFER_STORAGE_SLOT = keccak256("diamond.standard.storage.externaltransfer");

	struct Layout {
		/// @notice Counter for external transfer IDs
		/// @dev Auto-incremented when creating external transfers. Used as unique identifier
		///      for each external transfer request.
		uint256 lastExternalTransferId;
		/// @notice Stops cross protocol balance transfers when true
		/// @dev External transfers move funds between different protocols via
		///      relayer contracts. Pause this if the relayers are compromised.
		bool externalTransferPaused;
		/// @notice Relayer contracts authorized for external transfers to specific targets
		/// @dev Maps target address => authorized relayer. The relayer receives
		///      funds and deposits them on the target for the user.
		mapping(address => address) externalTransferTargetsRelayers;
		/// @notice External transfer request data by ID
		/// @dev Stores the full transfer request: sender, receiver, source/target contracts,
		///      amount, provider, and status. Provider must accept or user can cancel.
		mapping(uint256 => VirtualExternalTransferRequest) externalTransfers;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = EXTERNAL_TRANSFER_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/WithdrawStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice A single destination part within a multi-part withdrawal request
struct WithdrawReceiverPart {
	uint256 id;
	uint256 amount;
	int256 chainId;
	bytes receiver;
	address virtualProvider;
	address expressProvider;
}

/// @notice Full state of a withdrawal request including all destination parts and provider info
struct WithdrawRequest {
	uint256 id;
	address user;
	WithdrawReceiverPart[] parts;
	uint256 timestamp;
	uint256 cooldownEndTime;
	WithdrawStatus status;
	bool speedUp;
	bool isCooldownModified;
	address provider;
	bool isPureVirtual;
	bytes providerData;
	uint256 totalAmount;
	uint256 totalVirtualAmount;
}

/// @notice Lifecycle status of a withdrawal request
enum WithdrawStatus {
	PENDING,
	PROVIDER_ACCEPTED,
	PROVIDER_REJECTED,
	COMPLETED,
	CANCEL_REQUESTED,
	CANCELLED,
	SUSPENDED
}

/// @title WithdrawStorage
/// @notice Configuration and state for the new multi-part withdrawal system
/// @dev Supports complex withdrawals across chains with express and virtual providers.
library WithdrawStorage {
	bytes32 internal constant WITHDRAW_STORAGE_SLOT = keccak256("diamond.standard.storage.withdraw");

	struct Layout {
		/// @notice Maximum receiver parts allowed in a single withdrawal request
		/// @dev Limits complexity and gas costs. Users needing more destinations
		///      must submit multiple requests.
		uint256 maxWithdrawParts;
		/// @notice Minimum cooldown even with speed-up approval (seconds)
		/// @dev Even privileged users (solvers) can't reduce cooldown below this.
		///      Ensures some minimum time for monitoring.
		uint256 minWithdrawCooldown;
		/// @notice Blackout period before cooldown expiry during which pure virtual withdrawals cannot be cancelled (seconds)
		uint256 pureVirtualCancelBlackout;
		/// @notice Total balance locked across pending withdrawals and bridge transactions
		/// @dev Subtracted from contract balance to determine available funds. Ensures
		///      new withdrawals/bridges/transfers don't use funds already committed.
		uint256 withdrawLockedBalance;
		/// @notice Auto-incrementing request ID counter per user
		/// @dev Each user's requests are numbered sequentially starting from 1.
		///      Maps user => their last assigned request ID (0 means no requests yet).
		mapping(address => uint256) lastWithdrawRequestId;
		/// @notice All withdrawal requests indexed by user and request ID
		/// @dev Maps user => requestId => WithdrawRequest. The full request data
		///      including all parts and current status.
		mapping(address => mapping(uint256 => WithdrawRequest)) withdrawRequests;
		/// @notice Users allowed to request reduced cooldown periods
		/// @dev Only whitelisted addresses can set speedUp=true when requesting withdrawal.
		///      Typically solvers and other trusted automated systems.
		mapping(address => bool) speedUpWhitelist;
		/// @notice Whitelist of addresses that can act as virtual deposit/withdrawal providers
		/// @dev Virtual providers handle cross-chain deposits and withdrawals. They're trusted
		///      to credit user balances when funds are received on other chains.
		mapping(address => bool) virtualProviders;
		/// @notice Whitelist of addresses that can act as express withdrawal providers
		/// @dev Express providers front withdrawal funds to users immediately, then reclaim
		///      from Symmio after cooldown. They charge fees for this service. Must be
		///      registered here before they can accept withdrawal requests.
		mapping(address => bool) expressProviders;
		/// @notice Disables the legacy withdrawal path when true
		/// @dev The old withdrawal system is being phased out in favor of the new multi-part
		///      withdrawal system. Set this true once all users have migrated.
		bool legacyWithdrawalDeprecated;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = WITHDRAW_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    }
  }
